import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { loadData, run } from '../oracle/mine525b/check525b.mjs';

const DATA = loadData();

test('check525b как процесс: код выхода 0, критерий выполнен', () => {
  const r = spawnSync(process.execPath, ['oracle/mine525b/check525b.mjs'], { cwd: new URL('../', import.meta.url), encoding: 'utf8' });
  assert.equal(r.status, 0, r.stdout + r.stderr);
  assert.match(r.stdout, /Зн\(w1-mine-b, 100\): состояний 100, = O 100 — критерий выполнен/);
});

test('Зн(w1-mine-b, 100): 100 из 100, расхождения — только 2 известных кадра правила 27', () => {
  const r = run(DATA);
  assert.equal(r.znSame, 100);
  assert.equal(r.unknownBad.length, 0, JSON.stringify(r.unknownBad));
  assert.deepEqual(r.bad.map((b) => `${b.sc}:${b.f}`).sort(), ['w11:544', 'w2:1280']);
});

const spoil = (f) => { const d = structuredClone(DATA); f(d.mine.constants); return d; };
const PORCHI = {
  'hit.extraCooldown 15 → 14': (c) => { c['hit.extraCooldown'] = 14; },
  'roll.preWords 2 → 1': (c) => { c['roll.preWords'] = 1; },
  'hit.leadDie 99 → 98 (слов столько же)': (c) => { c['hit.leadDie'] = 98; },
  'hit.critDie 99 → 98': (c) => { c['hit.critDie'] = 98; },
  'rng.tickWords 4 → 3': (c) => { c['rng.tickWords'] = 3; },
  'floor.arrowWords 1 → 2': (c) => { c['floor.arrowWords'] = 2; },
};
for (const [name, f] of Object.entries(PORCHI)) {
  test(`порча: ${name} → Зн краснеет`, () => {
    let r;
    try { r = run(spoil(f)); } catch (e) { return; }
    assert.ok(r.znSame < 100, `${name}: Зн не заметил порчу`);
  });
}

test('порча входа: множитель золотой руды 5 → 4 → Зн краснеет', () => {
  const r = run(DATA, { tweakCells: (c) => { if (c.goldenOreMulti === 5) c.goldenOreMulti = 4; } });
  assert.ok(r.znSame < 100);
});

test('порча входа: множитель радужной руды 3 → 2 → Зн краснеет', () => {
  const r = run(DATA, { tweakCells: (c) => { if (c.rainbowOreMulti === 3) c.rainbowOreMulti = 2; } });
  assert.ok(r.znSame < 100);
});
